<script lang="ts">
 import ContextShell from '$lib/components/harness/ContextShell.svelte';
 import Icon from '$lib/components/harness/Icon.svelte';
 import {untrack} from 'svelte';
 import type {PageData} from './$types';
 let {data}:{data:PageData}=$props();
 import {parseContextReport,readContextReport,type ContextReport} from '$lib/harness/eval-report';
 let report=$state<ContextReport>(parseContextReport(untrack(()=>data.example))),uploadError=$state(''),uploaded=$state(false),copied=$state(false);
 const command='node plugins/context-evals/bin/loooom-context-eval.mjs \\\n  --suite plugins/context-evals/examples/suite.json \\\n  --context ./AGENTS.md \\\n  --output ./context-report.json';
 let baseline=$derived(report.results.filter(r=>r.baseline?.passed).length),context=$derived(report.results.filter(r=>r.context?.passed).length);
 async function upload(event:Event){uploadError='';const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;try{report=await readContextReport(file);uploaded=true;}catch(e){uploadError=e instanceof Error?e.message:'This report could not be opened.';}}
 async function copy(){try{await navigator.clipboard.writeText(command);copied=true;}catch{uploadError='Copy was blocked. Select the command below to copy it.';}}
</script>
<svelte:head><title>Personal evals — Loooom</title><meta name="description" content="Compare answers with and without your harness. Run personal evals locally and inspect the results."/></svelte:head>
<ContextShell><section class="eval-hero"><div class="page-intro"><a class="back-link" href="/">Back to discovery</a><h1>Test your<br/><span>harness.</span></h1><p>Same tasks. With and without your files. Compare the answers.</p><div class="eval-actions"><a class="button primary" href="#run-evals">Run an eval <Icon name="arrow" size={16}/></a><a class="text-link" href="#evidence">View the example <Icon name="arrow" size={15}/></a></div></div><div class="comparison-art" aria-hidden="true"><div><span>same task</span><i></i><span>same model</span></div><div class="comparison-side">without context<small>No personal files.</small></div><div class="comparison-side with-context">with your context<small>AGENTS.md + SOUL.md + ME.md</small></div><p>Compare both answers.</p></div></section>
 <section id="evidence" class="evidence"><div class="evidence-heading"><div><h2>Read the results.</h2><p>{report.suite.definition.name}</p></div><label class="button secondary upload"><Icon name="plus" size={16}/>Open your report<input type="file" accept=".json,application/json" onchange={upload}/></label></div>
 <p class="evidence-label" class:synthetic={report.evidence.synthetic||report.evidence.mode==='replay'}><Icon name="flask" size={16}/>{uploaded?'Local report · ':''}{report.evidence.synthetic?'Synthetic example. No model was called.':report.evidence.mode==='replay'?'Replayed answers. No model was called for this run.':'Reported live run. Loooom has not verified the model calls.'}</p>
 <p class="local-note">Reports stay in your browser. Checks measure specific rules, not overall model quality.</p>
 {#if report.status!=='complete'}<div class="notice" role="status">Incomplete run ({report.status}). {report.results.filter(result=>result.baseline||result.context).length} of {report.suite.definition.cases.length} cases have saved evidence. Missing answers are not scored.</div>{/if}
 {#if uploadError}<div class="notice error" role="alert">{uploadError}</div>{/if}
 <div class="result-summary"><span><strong>{baseline}<small>/{report.suite.definition.cases.length}</small></strong>baseline cases passed</span><Icon name="arrow" size={25}/><span><strong>{context}<small>/{report.suite.definition.cases.length}</small></strong>context cases passed</span><p>Check the answers.<br/>Passing text checks can miss errors.</p></div>
 <div class="result-table"><div class="result-table-head"><span>Test case</span><span>Without context</span><span>With context</span></div>{#each report.results as result}<details><summary><span>{result.caseId}<small>{result.prompt}</small></span><span class:pass={result.baseline?.passed}>{result.baseline===null?'Not run':result.baseline.passed?'Pass':'Fail'}</span><span class:pass={result.context?.passed}>{result.context===null?'Not run':result.context.passed?'Pass':'Fail'}</span></summary><div class="answer-pair">{#each [{label:'Without context',value:result.baseline},{label:'With context',value:result.context}] as side}<div><h3>{side.label}</h3><pre>{side.value?.output??'No response was recorded.'}</pre>{#if side.value}<ul>{#each side.value.assertions as assertion}<li><Icon name={assertion.passed?'check':'file'} size={13}/><span>{assertion.type}: {assertion.passed?'passed':'failed'}</span></li>{/each}</ul>{/if}</div>{/each}</div></details>{/each}</div>
 <div class="report-hashes"><span>Context SHA-256: {report.context.sha256}</span><span>Suite SHA-256: {report.suite.sha256}</span></div>
 </section>
 <section id="run-evals" class="run-section"><div><h2>Run it locally.</h2><p>Choose your files, tasks, and expected results.</p><ol><li>Clone Loooom and open the repository.</li><li>Copy the sample suite. Add your prompts and checks.</li><li>Set the endpoint, model, and key with environment variables.</li><li>Run paired tests. Open the saved report above.</li></ol><a class="text-link" href="/evals/plugin">Plugin guide <Icon name="arrow" size={15}/></a></div><div class="command-panel"><div><span>Node.js 22+ · no dependencies</span><button onclick={copy}><Icon name={copied?'check':'copy'} size={15}/>{copied?'Copied':'Copy'}</button></div><pre><code>{command}</code></pre><p>Add <code>--context ./SOUL.md</code> and <code>--context ./ME.md</code> to compare all three files. Live runs send them to your provider and may incur charges.</p></div></section>
 <div class="gym-link"><Icon name="layers" size={21}/><p>Skill repair and ablation tests: <a href="/gym">Visit the Gym. <Icon name="arrow" size={14}/></a></p></div>
</ContextShell>
